process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 10 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
pa() { for i in 1 2 3; do s=$(p "$1"); [ "$s" = 502 ] || break; sleep 2; done; echo "$s"; }
echo RANGE_START=$(pa 1.1.1.1:80)
echo RANGE_END=$(pa 1.1.1.1:443)
echo RANGE_BELOW=$(p 1.1.1.1:79)
echo RANGE_ABOVE=$(p 1.1.1.1:444)
echo RANGE_OUTSIDE=$(p 1.1.1.1:853)
echo LIST_FIRST=$(pa 8.8.8.8:443)
echo LIST_SECOND=$(pa 8.8.8.8:853)
echo LIST_OTHER=$(p 8.8.8.8:53)
echo ALL_PORTS_443=$(pa 9.9.9.9:443)
echo ALL_PORTS_853=$(pa 9.9.9.9:853)
echo UNLISTED=$(p 1.0.0.1:443)
